export type ServerMsg =
  | { type: "Welcome"; protocolVersion: number; playerId: number; tick: number }
  | { type: "Level"; data: LevelData }
  | { type: "Snapshot"; tick: number; level: number; lastInputSeq: number; you: ControllerState; players: PlayerView[]; enemies: EnemyView[]; giftsTaken: number[]; projectiles: ProjectileView[]; tiles: TileState[]; altarsUsed: number[]; levelPhase: number; goldenTaken: number[]; collapseMs: number }
  | { type: "Pong"; t: number }
  | { type: "Error"; code: number; message: string }
  | { type: "RunOver"; summary: RunSummary }
  | { type: "RunState"; info: RunInfo }
  | { type: "Draft"; enemyPicks: number; rewardPicks: number; cards: DraftCard[] }
  | { type: "Shop"; items: ShopItem[] }
  | { type: "Notice"; kind: number; ids: string[] }
  | { type: "VoteOpen"; level: number; options: VoteOption[]; countdownS: number }
  | { type: "VoteState"; counts: number[]; voted: number[]; secondsLeft: number }
  | { type: "VoteResult"; winner: number; id: string; name: string; kind: number; permanent: boolean }
  | { type: "DebugResult"; ok: boolean; message: string }
  | { type: "PollOpen"; options: PollOption[]; countdownS: number }
  | { type: "PollState"; counts: number[]; voted: number[]; secondsLeft: number }
  | { type: "PollResult"; winner: number; id: string; name: string; kind: number }
