export function writeServerMsg(w: Writer, v: ServerMsg): void {
  switch (v.type) {
    case "Welcome":
      w.u32(0);
      w.u16(v.protocolVersion);
      w.u32(v.playerId);
      w.u32(v.tick);
      return;
    case "Level":
      w.u32(1);
      writeLevelData(w, v.data);
      return;
    case "Snapshot":
      w.u32(2);
      w.u32(v.tick);
      w.u32(v.level);
      w.u32(v.lastInputSeq);
      writeControllerState(w, v.you);
      w.vec(v.players, (x) => writePlayerView(w, x));
      w.vec(v.enemies, (x) => writeEnemyView(w, x));
      w.vec(v.giftsTaken, (x) => w.u16(x));
      w.vec(v.projectiles, (x) => writeProjectileView(w, x));
      w.vec(v.tiles, (x) => writeTileState(w, x));
      w.vec(v.altarsUsed, (x) => w.u16(x));
      w.u8(v.levelPhase);
      w.vec(v.goldenTaken, (x) => w.u16(x));
      w.u32(v.collapseMs);
      return;
    case "Pong":
      w.u32(3);
      w.u32(v.t);
      return;
    case "Error":
      w.u32(4);
      w.u16(v.code);
      w.string(v.message);
      return;
    case "RunOver":
      w.u32(5);
      writeRunSummary(w, v.summary);
      return;
    case "RunState":
      w.u32(6);
      writeRunInfo(w, v.info);
      return;
    case "Draft":
      w.u32(7);
      w.u8(v.enemyPicks);
      w.u8(v.rewardPicks);
      w.vec(v.cards, (x) => writeDraftCard(w, x));
      return;
    case "Shop":
      w.u32(8);
      w.vec(v.items, (x) => writeShopItem(w, x));
      return;
    case "Notice":
      w.u32(9);
      w.u8(v.kind);
      w.vec(v.ids, (x) => w.string(x));
      return;
    case "VoteOpen":
      w.u32(10);
      w.u32(v.level);
      w.vec(v.options, (x) => writeVoteOption(w, x));
      w.u16(v.countdownS);
      return;
    case "VoteState":
      w.u32(11);
      w.vec(v.counts, (x) => w.u32(x));
      w.vec(v.voted, (x) => w.u32(x));
      w.u16(v.secondsLeft);
      return;
    case "VoteResult":
      w.u32(12);
      w.u8(v.winner);
      w.string(v.id);
      w.string(v.name);
      w.u8(v.kind);
      w.bool(v.permanent);
      return;
    case "DebugResult":
      w.u32(13);
      w.bool(v.ok);
      w.string(v.message);
      return;
    case "PollOpen":
      w.u32(14);
      w.vec(v.options, (x) => writePollOption(w, x));
      w.u16(v.countdownS);
      return;
    case "PollState":
      w.u32(15);
      w.vec(v.counts, (x) => w.u32(x));
      w.vec(v.voted, (x) => w.u32(x));
      w.u16(v.secondsLeft);
      return;
    case "PollResult":
      w.u32(16);
      w.u8(v.winner);
      w.string(v.id);
      w.string(v.name);
      w.u8(v.kind);
      return;
  }
}
export function readServerMsg(r: Reader): ServerMsg {
  const tag = r.u32();
  switch (tag) {
    case 0:
      return { type: "Welcome", protocolVersion: r.u16(), playerId: r.u32(), tick: r.u32() };
    case 1:
      return { type: "Level", data: readLevelData(r) };
    case 2:
      return { type: "Snapshot", tick: r.u32(), level: r.u32(), lastInputSeq: r.u32(), you: readControllerState(r), players: r.vec(() => readPlayerView(r)), enemies: r.vec(() => readEnemyView(r)), giftsTaken: r.vec(() => r.u16()), projectiles: r.vec(() => readProjectileView(r)), tiles: r.vec(() => readTileState(r)), altarsUsed: r.vec(() => r.u16()), levelPhase: r.u8(), goldenTaken: r.vec(() => r.u16()), collapseMs: r.u32() };
    case 3:
      return { type: "Pong", t: r.u32() };
    case 4:
      return { type: "Error", code: r.u16(), message: r.string() };
    case 5:
      return { type: "RunOver", summary: readRunSummary(r) };
    case 6:
      return { type: "RunState", info: readRunInfo(r) };
    case 7:
      return { type: "Draft", enemyPicks: r.u8(), rewardPicks: r.u8(), cards: r.vec(() => readDraftCard(r)) };
    case 8:
      return { type: "Shop", items: r.vec(() => readShopItem(r)) };
    case 9:
      return { type: "Notice", kind: r.u8(), ids: r.vec(() => r.string()) };
    case 10:
      return { type: "VoteOpen", level: r.u32(), options: r.vec(() => readVoteOption(r)), countdownS: r.u16() };
    case 11:
      return { type: "VoteState", counts: r.vec(() => r.u32()), voted: r.vec(() => r.u32()), secondsLeft: r.u16() };
    case 12:
      return { type: "VoteResult", winner: r.u8(), id: r.string(), name: r.string(), kind: r.u8(), permanent: r.bool() };
    case 13:
      return { type: "DebugResult", ok: r.bool(), message: r.string() };
    case 14:
      return { type: "PollOpen", options: r.vec(() => readPollOption(r)), countdownS: r.u16() };
    case 15:
      return { type: "PollState", counts: r.vec(() => r.u32()), voted: r.vec(() => r.u32()), secondsLeft: r.u16() };
    case 16:
      return { type: "PollResult", winner: r.u8(), id: r.string(), name: r.string(), kind: r.u8() };
    default:
      throw new Error(`ServerMsg: unknown variant tag ${tag}`);
  }
}
export function encodeServerMsg(v: ServerMsg): Uint8Array<ArrayBuffer> {
  const w = new Writer();
  writeServerMsg(w, v);
  return w.finish();
}
export function decodeServerMsg(bytes: Uint8Array): ServerMsg {
  const r = new Reader(bytes);
  const v = readServerMsg(r);
  r.end();
  return v;
}

